import { index, integer, pgEnum, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "./auth";

export const userEventAction = pgEnum("user_event_action", [
  "blocked",
  "unblocked",
  "signed_out",
  "promoted",
  "demoted",
]);

// What staff did to an account, written in the same statement as the change.
// Read with joins: user already has relations generated by Better Auth.
export const userEvents = pgTable(
  "user_events",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "restrict" }),
    actorId: text("actor_id")
      .notNull()
      .references(() => user.id, { onDelete: "restrict" }),
    action: userEventAction("action").notNull(),
    reason: text("reason"),
    // Devices signed out by this action
    sessionsEnded: integer("sessions_ended").default(0).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
  },
  (table) => [index("user_events_user_id_created_at_idx").on(table.userId, table.createdAt)],
);
